async function refreshOnline() {
  const keyObj = EnigmailKeyRing.getKeyById(gKeyId);
  if (!keyObj) {
    return;
  }

  const imported = await KeyLookupHelper.downloadDirectlyByFingerprint(
    "interactive-import",
    window,
    keyObj.fpr,
    true
  );
  if (imported) {
    onDataModified();
  }
}
